const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// RESCUE NOTE: v1 was too sparse — 3 plants, one taproot each, a 2% branch
// chance, and a network that needed ~40s to develop, so it read as "a few thin
// roots on brown". Fixed four ways: more plants each with several primary axes,
// a much higher branching rate to a 4th order, a BURN-IN that runs the growth
// model 300 steps at init so the profile is already full the instant it is
// fired (on stage nobody waits 40s for a visual to arrive), and real soil —
// aggregates, pores and mycorrhizal fuzz instead of a flat brown wash.

const BW = Math.max(360, Math.min(1180, Math.round(width * .68)));
const BH = Math.max(200, Math.round(BW * height / width));
const GW = 112, GH = Math.max(44, Math.round(GW * height / width));
const MAXT = 1100, MAXP = 10;
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };

const st = P.style;
