  S.soil = createGraphics(BW, BH); S.soil.pixelDensity(1);
  S.rt = createGraphics(BW, BH); S.rt.pixelDensity(1);
  S.wg = createGraphics(GW, GH); S.wg.pixelDensity(1);
  S.bw = BW; S.bh = BH; S.styleUsed = st; S.seedUsed = P.seed;
  S.tick = 0; S.step = 0; S.cur = 0; S.secUsed = -1; S.rainT = 0; S.burned = 0;
  // --- bake the soil cross-section: O / A / B / C horizons -----------------
  const so = S.soil; so.colorMode(HSB, 360, 100, 100, 100); so.noStroke();
  const prof = fy => {
    if (fy < .04) return soilV * .55;                       // O — litter
    if (fy < .27) return soilV * (.72 + (fy - .04) * .5);   // A — topsoil
    if (fy < .68) return soilV * (1.06 + (fy - .27) * .38); // B — subsoil
    return soilV * (1.2 - (fy - .68) * .34);                // C — parent material
  };
  for (let y = 0; y < BH; y++) {
    const fy = y / BH;
    const wob = (fr(y * .37 + 11) - .5) * 3.2 + Math.sin(y * .013 + fr(3) * 6.28) * 2.1;
    so.fill(0, 0, Math.max(2, Math.min(97, prof(fy) + wob)));
    so.rect(0, y, BW, 1);
  }
  const U0 = BW / 900;
  for (let i = 0; i < 7200; i++) {                          // grain + clasts
    const x = fr(i * 5 + 1) * BW, fy = fr(i * 5 + 2);
    const y = fy * BH, dep = fy;
    const sz = (.7 + fr(i * 5 + 3) * (1.1 + dep * dep * 9)) * U0 * 1.5;
    const dv = (fr(i * 5 + 4) - .42) * (14 + dep * 20);
    so.fill(0, 0, Math.max(2, Math.min(97, prof(fy) + dv)), 46 + fr(i * 5 + 5) * 40);
    so.ellipse(x, y, sz, sz * (.6 + fr(i * 7 + 2) * .7));
  }
  for (let i = 0; i < 1500; i++) {                          // peds: crumb aggregates
    const x = fr(i * 9 + 3) * BW, fy = fr(i * 9 + 4), y = fy * BH;
    const sz = (5 + fr(i * 9 + 5) * 16) * U0;
    so.noFill(); so.strokeWeight(Math.max(.6, U0));
    so.stroke(0, 0, Math.max(2, Math.min(97, prof(fy) - 9)), 26);
    so.ellipse(x, y, sz, sz * (.7 + fr(i * 9 + 6) * .6));
    so.noStroke();
    so.fill(0, 0, Math.max(2, Math.min(97, prof(fy) + 7)), 12);
    so.ellipse(x - sz * .12, y - sz * .12, sz * .7, sz * .55);
  }
  for (let i = 0; i < 900; i++) {                           // pores / voids
    const x = fr(i * 11 + 5) * BW, fy = fr(i * 11 + 6), y = fy * BH;
    const sz = (1.4 + fr(i * 11 + 7) * 5) * U0;
    so.fill(0, 0, Math.max(1, prof(fy) * .38), 52 + fr(i * 11 + 8) * 34);
    so.ellipse(x, y, sz, sz * (.5 + fr(i * 13 + 2) * .9));
  }
  for (let i = 0; i < 34; i++) {                            // horizon boundary flecks
    const y = (.27 + (fr(i * 3 + 71) - .5) * .05) * BH;
    so.fill(0, 0, Math.min(97, soilV * .6), 30);
    so.ellipse(fr(i * 3 + 72) * BW, y, (24 + fr(i * 3 + 73) * 60) * U0, (4 + fr(i * 3 + 74) * 7) * U0);
  }
  S.rt.colorMode(HSB, 360, 100, 100, 100);
  S.rt.image(S.soil, 0, 0);
  S.w = new Float32Array(GW * GH); S.w2 = new Float32Array(GW * GH);
  for (let y = 0; y < GH; y++) for (let x = 0; x < GW; x++) S.w[y * GW + x] = .18 + (y / GH) * .6 + fr(y * GW + x) * .1;
  S.tx = new Float32Array(MAXT); S.ty = new Float32Array(MAXT); S.px = new Float32Array(MAXT); S.py = new Float32Array(MAXT);
  S.td = new Float32Array(MAXT); S.ta = new Float32Array(MAXT); S.to = new Uint8Array(MAXT); S.tp = new Uint8Array(MAXT); S.al = new Uint8Array(MAXT);
