}

const soil = S.soil, rt = S.rt, wg = S.wg, W = S.w, W2 = S.w2;
const tx = S.tx, ty = S.ty, ppx = S.px, ppy = S.py, td = S.td, ta = S.ta, to = S.to, tp = S.tp, al = S.al;
const plX = S.plX, plA = S.plA, plL = S.plL, plAl = S.plAl;
S.tick = (S.tick || 0) + 1;
// salted on S.step (not S.tick) so the burn-in below is not a degenerate loop
// that grows every root in a perfectly straight line
const rnd = k => { const s = Math.sin(k * 12.9898 + S.step * .6180339 + P.seed * 7.13) * 43758.5453; return s - Math.floor(s); };
const U = BW / 900;
const TAU = Math.PI * 2;

// ---- act: multi-minute climate --------------------------------------------
let clim;
if (P.act === 'monsoon') clim = 1.85;
else if (P.act === 'drought') clim = .3;
else clim = .4 + 1.4 * (.5 + .5 * Math.sin(K.t * .0107 + .85 * Math.sin(K.t * .0039 + .6)));

// ---- rain events on section change; water percolates downward -------------
if (S.secUsed !== K.section) { S.secUsed = K.section; S.rainT = (70 + rnd(1) * 150) * clim; }
if (S.rainT > 0) S.rainT -= 1;
const rainNow = (S.rainT > 0 ? .010 : .0013) * clim * (.6 + .5 * K.intensity + .5 * A.rms);
W2.set(W);
for (let y = 0; y < GH; y++) for (let x = 0; x < GW; x++) {
  const i = y * GW + x;
  if (y === 0) { W2[i] = Math.min(1.25, W[i] + rainNow); continue; }
  if (y >= GH - 2) { W2[i] = W[i] + (1.05 - W[i]) * .02; continue; }   // water table recharge
