}
W.set(W2);

const aging = .4 + P.speed * .9;
const nWant = 2 + Math.round(P.density * 5);
const SP = (.42 + P.energy * .95) * (.45 + P.speed * .8) * U;
const brP = (.010 + P.branch * .045) * (.4 + P.speed * .8);
const wAt = (gx, gy) => {
  let ix = Math.floor(gx), iy = Math.floor(gy);
  if (ix < 0) ix = 0; if (iy < 0) iy = 0; if (ix >= GW) ix = GW - 1; if (iy >= GH) iy = GH - 1;
  return W[iy * GW + ix];
