const spawnTip = (x, y, d, o, p) => {
  for (let n = 0; n < MAXT; n++) {
    S.cur = (S.cur + 1) % MAXT;
    if (!al[S.cur]) { const k = S.cur; al[k] = 1; tx[k] = x; ty[k] = y; ppx[k] = x; ppy[k] = y; td[k] = d; ta[k] = 0; to[k] = o; tp[k] = p; return true; }
  }
