rt.strokeCap(ROUND);

// ---- one step of the growth model (called once per frame, and 300x at init) --
const growStep = () => {
  S.step = (S.step || 0) + 1;
  // the old network fades back into the soil so the profile keeps churning
  if (S.step % 36 === 0) { rt.push(); rt.tint(0, 0, 100, .6 + P.speed * .3); rt.image(soil, 0, 0); rt.pop(); }
  // --- plant generations ---
  let nAlivePl = 0;
  for (let p = 0; p < MAXP; p++) {
    if (!plAl[p]) continue;
    nAlivePl++;
    plA[p] += aging;
    if (plA[p] > plL[p]) { plAl[p] = 0; for (let k = 0; k < MAXT; k++) if (al[k] && tp[k] === p) al[k] = 0; }
  }
