    for (let p = 0; p < MAXP; p++) if (!plAl[p]) {
      let bx = .5, bd = -1;
      for (let q = 0; q < 6; q++) {                              // germinate away from standing plants
        const cx = .06 + rnd(p * 17 + q * 3 + 1) * .88;
        let mn = 9;
        for (let o = 0; o < MAXP; o++) if (plAl[o]) mn = Math.min(mn, Math.abs(plX[o] - cx));
        const sc = mn - Math.abs(cx - P.x) * .5;                 // seed rain centred on the anchor
        if (sc > bd) { bd = sc; bx = cx; }
      }
      plAl[p] = 1; plX[p] = bx; plA[p] = 0; plL[p] = 2600 + rnd(p * 23 + 5) * 2600;
      // several primary axes, not a single taproot — this is a root SYSTEM
      const nax = 2 + Math.round(rnd(p * 31 + 9) * 2);
      for (let a2 = 0; a2 < nax; a2++)
        spawnTip(bx * BW, P.y * BH, Math.PI / 2 + (a2 - (nax - 1) / 2) * .42 + (rnd(p * 29 + a2 * 7 + 3) - .5) * .22, 0, p);
      break;
    }
