  let alive = 0;
  for (let k = 0; k < MAXT; k++) {
    if (!al[k]) continue;
    alive++;
    const o = to[k];
    let d = td[k];
    // gravitropism (order-graded) + hydrotropism + persistence noise
    const grav = o === 0 ? .052 : o === 1 ? .0065 : .015;
    let da = Math.PI / 2 - d; while (da > Math.PI) da -= TAU; while (da < -Math.PI) da += TAU;
    d += da * grav;
