    const wr = wAt(gx + Math.cos(d + .7) * sd, gy + Math.sin(d + .7) * sd);
    d += (wr - wl) * (.14 + P.energy * .22);
    d += (rnd(k * 3 + 1) - .5) * (.06 + o * .05 + (1 - P.energy) * .07);
    td[k] = d;
    const spd = o === 0 ? 1.25 : o === 1 ? .95 : o === 2 ? .7 : .5;
    const nx = tx[k] + Math.cos(d) * SP * spd;
    const ny = ty[k] + Math.sin(d) * SP * spd;
    if (nx < 3 || nx > BW - 3 || ny > BH - 3 || ny < 1) { al[k] = 0; continue; }
    const gi = Math.min(GH - 1, Math.max(0, Math.floor(ny / BH * GH))) * GW + Math.min(GW - 1, Math.max(0, Math.floor(nx / BW * GW)));
    W[gi] = Math.max(0, W[gi] - (.0022 + P.energy * .0034) * (.4 + P.speed * .7));
