      rt.noStroke(); rt.fill(0, 0, rootV, 7);
      const fz = (5 + rnd(k * 17 + 5) * 9) * U * (.6 + P.density * .8);
      rt.ellipse(nx, ny, fz, fz * (.7 + rnd(k * 17 + 6) * .6));
      rt.noFill();
    }
    ppx[k] = nx; ppy[k] = ny; tx[k] = nx; ty[k] = ny; ta[k]++;
