    if (o < 4 && alive < MAXT - 8 && ta[k] > 10 && rnd(k * 9 + 5) < brP * (.35 + wAt(gx, gy)) * (o === 0 ? 1.6 : .85)) {
      const side = rnd(k * 11 + 7) > .5 ? 1 : -1;
      spawnTip(nx, ny, d + side * (o === 0 ? 1.05 + rnd(k * 13) * .4 : .55 + rnd(k * 13) * .5), o + 1, tp[k]);
    }
