for (let i = 0; i < GW * GH; i++) {
  const v = 255 - Math.min(1, W[i] * .92) * wetK;
  const q = 4 * i; wp[q] = v; wp[q + 1] = v * .995; wp[q + 2] = v * (st === 'ink' ? 1 : .96); wp[q + 3] = 255;
}
wg.updatePixels();

const drift = .5 + .5 * Math.sin(K.t * .071 + .55 * Math.sin(K.t * .0263 + 1.2));
const expo = 64 + P.energy * 28 + K.intensity * 7 + A.rms * 16 + drift * 8;
push();
